answer:
Below is the implementation of C program to find the number of arguments and length properties:

```c
#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if(argc == 1) {
        printf("No arguments provided. Please provide command line arguments.\n");
        return -1;
    }

    int i;
    int max_len = strlen(argv[1]);
    int min_len = strlen(argv[1]);
    int sum_len = 0;
    char *longest_arg = argv[1];
    char *shortest_arg = argv[1];

    for(i=1; i < argc; i++) {
        int len = strlen(argv[i]);
        sum_len += len;

        if(len > max_len) {
            max_len = len;
            longest_arg = argv[i];
        }

        if(len < min_len) {
            min_len = len;
            shortest_arg = argv[i];
        }
    }

    printf("Total number of arguments provided: %d\n", argc - 1);    // argc also contains the program's name as argument
    printf("The longest argument \"%s\" has %d characters.\n", longest_arg, max_len);
    printf("The shortest argument \"%s\" has %d characters.\n", shortest_arg, min_len);
    printf("The sum of the lengths of all arguments is %d.\n", sum_len);

    return 0;
}
```
This program accepts command line arguments list, check if arguments are provided or not. If not, it prints appropriate error message. If arguments are given, it will calculate maximum, minimum and total length of the arguments and prints them on console.

