    public static List<String> mostCommonWords(String str) {
        List<String> result = new ArrayList<>();
        if (str == null || str.isEmpty()) {
            return result;
        }

        String[] words = str.toLowerCase().split("\\s+");
        Map<String, Integer> wordCount = new HashMap<>();

