const meanAbsoluteDeviation = (numbers) => {
    // Calculate the mean
    let mean = numbers.reduce((acc, val) => acc + val, 0) / numbers.length;

    // Calculate the absolute deviations from the mean
    let deviations = numbers.map((val) => Math.abs(val - mean));

