You are given a piece of code as a starting point. This code doesn't work in the current state. 

```javascript
var couchdb = require('couchdb');
var database = couchdb.create('http://localhost:5984/my_database');
database.insert('my_id', {name: 'My Document'}, function(err, body, headers) {
  if (!err) {
