def process_logs(logs, start_time, end_time):
    from datetime import datetime

    def convert_timestamp(timestamp_str):
        return datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")

    start_time_obj = convert_timestamp(start_time)
    end_time_obj = convert_timestamp(end_time)

    unique_filenames = set()

    for log in logs:
        timestamp_obj = convert_timestamp(log["timestamp"])
        if start_time_obj <= timestamp_obj <= end_time_obj:
            unique_filenames.add(log["filename"])

    return sorted(list(unique_filenames))
